// ---- Persistence-free progress reducer ----
function progressReducer(state, action) {
  switch (action.type) {
    case "answer": {
      const prev = state[action.key] || { seen: 0, correct: 0, streak: 0, missed: false };
      const seen = prev.seen + 1;
      const correct = prev.correct + (action.correct ? 1 : 0);
      const streak = action.correct ? prev.streak + 1 : 0;
      const missed = action.correct ? (streak >= 2 ? false : prev.missed) : true;
      return { ...state, [action.key]: { seen, correct, streak, missed, topicId: action.topicId, bookmarked: prev.bookmarked || false, lastSeen: Date.now() } };
    }
    case "bookmark": {
      const prev = state[action.key] || { seen: 0, correct: 0, streak: 0, missed: false, topicId: action.topicId };
      return { ...state, [action.key]: { ...prev, topicId: action.topicId, bookmarked: !prev.bookmarked } };
    }
    case "logExam": {
      const hist = Array.isArray(state.__examHistory) ? state.__examHistory : [];
      const entry = { at: Date.now(), correct: action.correct, total: action.total, pct: action.pct, byTopic: action.byTopic };
      return { ...state, __examHistory: [...hist, entry].slice(-25) };
    }
    case "hydrate":
      return action.payload || {};
    case "reset":
      return {};
    default:
      return state;
  }
}

// ---- Small UI atoms ----
function ProgressBar({ value, height = 6, track = T.lineSoft, fill = T.brand }) {
  return (
    <div style={{ height, background: track, borderRadius: 999, overflow: "hidden", width: "100%" }}>
      <div style={{ width: `${Math.max(0, Math.min(100, value))}%`, height: "100%", background: fill, borderRadius: 999, transition: "width 600ms cubic-bezier(0.22,1,0.36,1)" }} />
    </div>
  );
}

function Ring({ pct, size = 56, stroke = 5 }) {
  const r = (size - stroke) / 2;
  const c = 2 * Math.PI * r;
  const off = c - (pct / 100) * c;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ display: "block" }}>
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke={T.lineSoft} strokeWidth={stroke} />
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke={T.brand} strokeWidth={stroke} strokeLinecap="round" strokeDasharray={c} strokeDashoffset={off} transform={`rotate(-90 ${size / 2} ${size / 2})`} style={{ transition: "stroke-dashoffset 700ms cubic-bezier(0.22,1,0.36,1)" }} />
      <text x="50%" y="50%" dominantBaseline="central" textAnchor="middle" style={{ fontSize: size * 0.26, fontWeight: 600, fill: T.ink, fontFamily: T.font }}>{Math.round(pct)}%</text>
    </svg>
  );
}

function Pill({ children, color, bg }) {
  return (
    <span style={{ fontSize: 11.5, fontWeight: 600, letterSpacing: "0.02em", padding: "3px 10px", borderRadius: 999, color, background: bg, whiteSpace: "nowrap" }}>{children}</span>
  );
}

// ---- Question card ----
function QuestionCard({ q, qKey, onAnswer, showTopic }) {
  const [picked, setPicked] = useState(null);
  const answered = picked !== null;
  const d = DIFF[q.d] || DIFF.easy;
  return (
    <div style={{ background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, padding: 22, boxShadow: T.shadowSm }}>
      <div style={{ display: "flex", gap: 10, alignItems: "center", marginBottom: 14 }}>
        <Pill color={d.color} bg={d.bg}>{d.label}</Pill>
        {showTopic && <span style={{ fontSize: 12.5, color: T.inkFaint, fontWeight: 500 }}>{q.topicName}</span>}
      </div>
      <p style={{ margin: 0, fontSize: 16, lineHeight: 1.55, fontWeight: 500, color: T.ink }}>{q.q}</p>
      <div style={{ marginTop: 16, display: "flex", flexDirection: "column", gap: 9 }}>
        {q.choices.map((choice, ci) => {
          const isAnswer = ci === q.answer;
          const isPicked = ci === picked;
          let border = T.line, bg = T.surface, color = T.ink, badgeBg = T.surfaceAlt, badgeColor = T.inkSoft;
          if (answered) {
            if (isAnswer) { border = T.brand; bg = T.brandTint; color = T.brandDeep; badgeBg = T.brand; badgeColor = "#fff"; }
            else if (isPicked) { border = T.rose; bg = T.roseSoft; color = T.rose; badgeBg = T.rose; badgeColor = "#fff"; }
            else { color = T.inkFaint; }
          }
          return (
            <button key={ci} disabled={answered} onClick={() => { setPicked(ci); onAnswer(ci === q.answer); }}
              style={{ display: "flex", alignItems: "flex-start", gap: 12, textAlign: "left", padding: "13px 15px", borderRadius: T.radiusSm, border: `1.5px solid ${border}`, background: bg, color, fontSize: 14.5, lineHeight: 1.5, cursor: answered ? "default" : "pointer", transition: "all 180ms ease", fontFamily: T.font, width: "100%" }}
              onMouseEnter={(e) => { if (!answered) { e.currentTarget.style.borderColor = T.brand; e.currentTarget.style.background = T.brandTint; } }}
              onMouseLeave={(e) => { if (!answered) { e.currentTarget.style.borderColor = T.line; e.currentTarget.style.background = T.surface; } }}>
              <span style={{ flexShrink: 0, width: 22, height: 22, borderRadius: 6, background: badgeBg, color: badgeColor, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontWeight: 700, transition: "all 180ms ease" }}>{String.fromCharCode(65 + ci)}</span>
              <span style={{ paddingTop: 1 }}>{choice}</span>
            </button>
          );
        })}
      </div>
      {answered && (
        <div style={{ marginTop: 16, display: "flex", flexDirection: "column", gap: 8, animation: "fadeIn 300ms ease" }}>
          {q.choices.map((choice, ci) => {
            const isAnswer = ci === q.answer;
            const isPicked = ci === picked;
            if (!isAnswer && !isPicked) return (
              <div key={ci} style={{ fontSize: 13, lineHeight: 1.55, padding: "8px 12px", borderRadius: 8, background: T.surfaceAlt, color: T.inkFaint }}>
                <strong style={{ color: T.inkSoft }}>{String.fromCharCode(65 + ci)}.</strong> {q.why[ci]}
              </div>
            );
            return (
              <div key={ci} style={{ fontSize: 13.5, lineHeight: 1.55, padding: "10px 13px", borderRadius: 9, background: isAnswer ? T.brandSoft : T.roseSoft, color: isAnswer ? T.brandDeep : T.rose, border: `1px solid ${isAnswer ? T.brand : T.rose}22` }}>
                <strong>{String.fromCharCode(65 + ci)}.</strong> {q.why[ci]}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

