// ---- Money formatter for entries ----
function fmtAmt(n) {
  return n.toLocaleString("en-US", { minimumFractionDigits: 0, maximumFractionDigits: 0 });
}

// ---- Journal entry: standard 2-column (Account / Debit / Credit), credits indented ----
function JournalEntry({ entry }) {
  const totalDr = entry.lines.reduce((a, l) => a + (l.dr || 0), 0);
  const totalCr = entry.lines.reduce((a, l) => a + (l.cr || 0), 0);
  const balanced = Math.abs(totalDr - totalCr) < 0.5;
  // Column accent palette (dark mode)
  const debitC = "#5FCF9C", debitBg = "rgba(63,185,133,0.16)", debitBgSoft = "rgba(63,185,133,0.07)";
  const creditC = "#E0A93C", creditBg = "rgba(224,169,60,0.16)", creditBgSoft = "rgba(224,169,60,0.07)";
  const mono = "ui-monospace, 'SF Mono', Menlo, monospace";
  return (
    <div style={{ marginTop: 16 }}>
      <div style={{ fontSize: 13, fontWeight: 600, color: T.inkSoft, marginBottom: 9, lineHeight: 1.45 }}>{entry.caption}</div>
      <div style={{ borderRadius: 14, overflow: "hidden", boxShadow: "0 2px 10px rgba(0,0,0,0.4)", border: `1px solid ${T.line}` }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13.5 }}>
          <thead>
            <tr style={{ background: "linear-gradient(135deg, #0A0B09, #1E211B)" }}>
              <th style={{ textAlign: "left", padding: "11px 16px", fontWeight: 700, color: "rgba(242,241,234,0.5)", fontSize: 10.5, letterSpacing: "0.08em", textTransform: "uppercase", fontFamily: T.font }}>Account</th>
              <th style={{ textAlign: "right", padding: "11px 16px", fontWeight: 700, color: "#5FCF9C", fontSize: 10.5, letterSpacing: "0.08em", textTransform: "uppercase", fontFamily: T.font, width: 120, borderLeft: "1px solid rgba(255,255,255,0.06)" }}>Debit</th>
              <th style={{ textAlign: "right", padding: "11px 16px", fontWeight: 700, color: "#E0A93C", fontSize: 10.5, letterSpacing: "0.08em", textTransform: "uppercase", fontFamily: T.font, width: 120, borderLeft: "1px solid rgba(255,255,255,0.06)" }}>Credit</th>
            </tr>
          </thead>
          <tbody>
            {entry.lines.map((l, i) => {
              const isCredit = (l.cr || 0) > 0;
              const accentC = isCredit ? creditC : debitC;
              return (
                <tr key={i} style={{ borderTop: i === 0 ? "none" : `1px solid ${T.lineSoft}`, background: T.surface }}>
                  <td style={{ padding: "11px 16px", color: T.ink, paddingLeft: isCredit ? 44 : 16, fontFamily: T.font, fontWeight: 500 }}>
                    <span style={{ display: "inline-flex", alignItems: "center", gap: 8 }}>
                      <span style={{ width: 7, height: 7, borderRadius: 999, background: accentC, flexShrink: 0, boxShadow: `0 0 0 3px ${isCredit ? creditBg : debitBg}` }} />
                      {l.account}
                    </span>
                  </td>
                  <td style={{ padding: "11px 16px", textAlign: "right", color: l.dr ? debitC : T.inkFaint, background: debitBgSoft, fontFamily: mono, fontWeight: l.dr ? 600 : 400 }}>{l.dr ? fmtAmt(l.dr) : "—"}</td>
                  <td style={{ padding: "11px 16px", textAlign: "right", color: l.cr ? creditC : T.inkFaint, background: creditBgSoft, fontFamily: mono, fontWeight: l.cr ? 600 : 400 }}>{l.cr ? fmtAmt(l.cr) : "—"}</td>
                </tr>
              );
            })}
            <tr style={{ borderTop: `2px solid ${T.line}` }}>
              <td style={{ padding: "11px 16px", fontWeight: 700, color: T.ink, fontFamily: T.font, fontSize: 12.5, background: T.surfaceAlt }}>
                <span style={{ display: "inline-flex", alignItems: "center", gap: 8 }}>
                  Totals
                  {balanced && (
                    <span style={{ display: "inline-flex", alignItems: "center", gap: 4, fontSize: 10.5, fontWeight: 700, color: debitC, background: debitBg, padding: "2px 8px", borderRadius: 999, letterSpacing: "0.02em" }}>
                      <span style={{ fontSize: 11 }}>✓</span> Balanced
                    </span>
                  )}
                </span>
              </td>
              <td style={{ padding: "11px 16px", textAlign: "right", fontWeight: 700, color: debitC, background: debitBg, fontFamily: mono, borderTop: `2px solid ${debitC}` }}>{fmtAmt(totalDr)}</td>
              <td style={{ padding: "11px 16px", textAlign: "right", fontWeight: 700, color: creditC, background: creditBg, fontFamily: mono, borderTop: `2px solid ${creditC}` }}>{fmtAmt(totalCr)}</td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}

// ---- Computation table (for EPS, cash flows — no journal entries) ----
function ComputationTable({ table }) {
  return (
    <div style={{ marginTop: 14 }}>
      <div style={{ fontSize: 13, fontWeight: 600, color: T.inkSoft, marginBottom: 7 }}>{table.title}</div>
      <div style={{ border: `1px solid ${T.line}`, borderRadius: T.radiusSm, overflow: "hidden", background: T.surface }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13.5 }}>
          <tbody>
            {table.rows.map((r, i) => {
              const last = table.highlightLast && i === table.rows.length - 1;
              return (
                <tr key={i} style={{ borderTop: i === 0 ? "none" : `1px solid ${T.lineSoft}`, background: last ? T.brandTint : "transparent" }}>
                  <td style={{ padding: "9px 14px", color: last ? T.brandDeep : T.ink, fontWeight: last ? 700 : 400, lineHeight: 1.45 }}>{r[0]}</td>
                  <td style={{ padding: "9px 14px", textAlign: "right", color: last ? T.brandDeep : T.ink, fontWeight: last ? 700 : 500, fontFamily: "ui-monospace, 'SF Mono', Menlo, monospace", whiteSpace: "nowrap" }}>{r[1]}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function WorkedBlock({ worked, entries, comptable }) {
  const hasEntries = entries && entries.length > 0;
  return (
    <div style={{ background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, padding: 24, boxShadow: T.shadowSm }}>
      <h3 style={{ margin: 0, fontSize: 18, fontWeight: 600, color: T.ink, fontFamily: T.serif, letterSpacing: "-0.01em" }}>{worked.title}</h3>
      <div style={{ marginTop: 14, padding: "14px 16px", background: T.blueSoft, borderRadius: T.radiusSm, borderLeft: `3px solid ${T.blue}` }}>
        <span style={{ fontSize: 11.5, fontWeight: 700, letterSpacing: "0.04em", textTransform: "uppercase", color: T.blue }}>The problem</span>
        <p style={{ margin: "6px 0 0", fontSize: 14.5, lineHeight: 1.6, color: T.ink }}>{worked.setup}</p>
      </div>
      <ol style={{ listStyle: "none", margin: "18px 0 0", padding: 0, counterReset: "step" }}>
        {worked.steps.map((s, i) => (
          <li key={i} style={{ display: "flex", gap: 14, paddingBottom: i === worked.steps.length - 1 ? 0 : 16 }}>
            <div style={{ flexShrink: 0, display: "flex", flexDirection: "column", alignItems: "center" }}>
              <span style={{ width: 28, height: 28, borderRadius: 999, background: T.brand, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 13, fontWeight: 700, boxShadow: T.shadowSm }}>{i + 1}</span>
              {i !== worked.steps.length - 1 && <span style={{ flex: 1, width: 2, background: T.lineSoft, marginTop: 4, minHeight: 16 }} />}
            </div>
            <div style={{ flex: 1, paddingBottom: 2 }}>
              <div style={{ fontSize: 14.5, fontWeight: 600, lineHeight: 1.5, color: T.ink }}>{s.do}</div>
              <div style={{ fontSize: 13.5, lineHeight: 1.6, color: T.inkSoft, marginTop: 5 }}><span style={{ color: T.brand, fontWeight: 600 }}>Why — </span>{s.why}</div>
            </div>
          </li>
        ))}
      </ol>

      {(hasEntries || comptable) && (
        <div style={{ marginTop: 20, paddingTop: 18, borderTop: `1px dashed ${T.line}` }}>
          <span style={{ fontSize: 11.5, fontWeight: 700, letterSpacing: "0.04em", textTransform: "uppercase", color: T.inkFaint }}>{hasEntries ? "Journal entries" : "Computation"}</span>
          {hasEntries && entries.map((e, i) => <JournalEntry key={i} entry={e} />)}
          {!hasEntries && comptable && <ComputationTable table={comptable} />}
        </div>
      )}

      <div style={{ marginTop: 18, padding: "14px 16px", background: T.brandTint, borderRadius: T.radiusSm, borderLeft: `3px solid ${T.brand}` }}>
        <span style={{ fontSize: 11.5, fontWeight: 700, letterSpacing: "0.04em", textTransform: "uppercase", color: T.brandDeep }}>The takeaway</span>
        <p style={{ margin: "6px 0 0", fontSize: 14.5, lineHeight: 1.6, color: T.brandDeep }}>{worked.takeaway}</p>
      </div>
    </div>
  );
}


