function EntryBuilder({ entry, index }) {
  // Student fills debit/credit for each line. Account names are given (in shuffled-safe original order).
  const [vals, setVals] = useState(entry.lines.map(() => ({ dr: "", cr: "" })));
  const [checked, setChecked] = useState(false);
  const mono = "ui-monospace, 'SF Mono', Menlo, monospace";

  const parse = (s) => { const n = parseFloat(String(s).replace(/[^0-9.\-]/g, "")); return isNaN(n) ? 0 : n; };
  const lineCorrect = (i) => {
    const want = entry.lines[i];
    return parse(vals[i].dr) === (want.dr || 0) && parse(vals[i].cr) === (want.cr || 0);
  };
  const totalDr = vals.reduce((a, v) => a + parse(v.dr), 0);
  const totalCr = vals.reduce((a, v) => a + parse(v.cr), 0);
  const balanced = Math.abs(totalDr - totalCr) < 0.5 && totalDr > 0;
  const allCorrect = entry.lines.every((_, i) => lineCorrect(i));

  const setVal = (i, field, v) => { const c = vals.map((x) => ({ ...x })); c[i][field] = v; setVals(c); setChecked(false); };
  const fmt = (n) => n.toLocaleString("en-US");

  const inputStyle = (ok) => ({
    width: 96, padding: "7px 9px", textAlign: "right", borderRadius: 7,
    border: `1.5px solid ${checked ? (ok ? T.brand : T.rose) : T.line}`,
    background: checked ? (ok ? "rgba(63,185,133,0.1)" : "rgba(232,115,106,0.1)") : T.surface,
    color: T.ink, fontFamily: mono, fontSize: 13.5, outline: "none",
  });

  return (
    <div style={{ background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, padding: 22, boxShadow: T.shadowSm }}>
      <div style={{ display: "flex", gap: 12, marginBottom: 14 }}>
        <span style={{ flexShrink: 0, width: 28, height: 28, borderRadius: 999, background: T.surfaceAlt, color: T.brandDeep, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 13, fontWeight: 700, border: `1.5px solid ${T.brand}` }}>{index + 1}</span>
        <p style={{ margin: 0, fontSize: 14.5, lineHeight: 1.5, fontWeight: 500, color: T.ink, paddingTop: 4 }}>{entry.caption}</p>
      </div>
      <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 13.5 }}>
        <thead>
          <tr>
            <th style={{ textAlign: "left", padding: "6px 4px", fontSize: 11, fontWeight: 700, color: T.inkFaint, textTransform: "uppercase", letterSpacing: "0.05em" }}>Account</th>
            <th style={{ textAlign: "right", padding: "6px 4px", fontSize: 11, fontWeight: 700, color: T.inkFaint, textTransform: "uppercase", letterSpacing: "0.05em", width: 110 }}>Debit</th>
            <th style={{ textAlign: "right", padding: "6px 4px", fontSize: 11, fontWeight: 700, color: T.inkFaint, textTransform: "uppercase", letterSpacing: "0.05em", width: 110 }}>Credit</th>
          </tr>
        </thead>
        <tbody>
          {entry.lines.map((l, i) => {
            const isCredit = (l.cr || 0) > 0;
            const ok = lineCorrect(i);
            return (
              <tr key={i} style={{ borderTop: `1px solid ${T.lineSoft}` }}>
                <td style={{ padding: "8px 4px", color: T.ink, paddingLeft: isCredit ? 28 : 4 }}>{l.account}</td>
                <td style={{ padding: "8px 4px", textAlign: "right" }}><input inputMode="numeric" value={vals[i].dr} onChange={(e) => setVal(i, "dr", e.target.value)} placeholder="—" style={inputStyle(checked && ok)} /></td>
                <td style={{ padding: "8px 4px", textAlign: "right" }}><input inputMode="numeric" value={vals[i].cr} onChange={(e) => setVal(i, "cr", e.target.value)} placeholder="—" style={inputStyle(checked && ok)} /></td>
              </tr>
            );
          })}
          <tr style={{ borderTop: `2px solid ${T.line}` }}>
            <td style={{ padding: "8px 4px", fontWeight: 700, color: T.inkSoft, fontSize: 12 }}>Totals</td>
            <td style={{ padding: "8px 4px", textAlign: "right", fontWeight: 700, color: balanced ? T.brand : T.inkSoft, fontFamily: mono }}>{fmt(totalDr)}</td>
            <td style={{ padding: "8px 4px", textAlign: "right", fontWeight: 700, color: balanced ? T.brand : T.inkSoft, fontFamily: mono }}>{fmt(totalCr)}</td>
          </tr>
        </tbody>
      </table>
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginTop: 14, flexWrap: "wrap" }}>
        <button onClick={() => setChecked(true)} style={{ background: T.brand, color: "#0E0F0D", border: "none", borderRadius: T.radiusSm, padding: "9px 18px", fontSize: 13.5, fontWeight: 600, cursor: "pointer", fontFamily: T.font }}>Check entry</button>
        <button onClick={() => { setVals(entry.lines.map(() => ({ dr: "", cr: "" }))); setChecked(false); }} style={{ background: "transparent", color: T.inkSoft, border: `1px solid ${T.line}`, borderRadius: T.radiusSm, padding: "9px 16px", fontSize: 13.5, fontWeight: 500, cursor: "pointer", fontFamily: T.font }}>Clear</button>
        {checked && (
          <span style={{ fontSize: 13.5, fontWeight: 600, color: allCorrect ? T.brand : T.gold }}>
            {allCorrect ? "✓ Correct — and it balances." : balanced ? "Balanced, but some amounts are off. Check the highlighted cells." : "Not balanced yet — debits must equal credits."}
          </span>
        )}
      </div>
    </div>
  );
}

