function TopicTutor({ topic }) {
  const [messages, setMessages] = useState([]); // {role, content}
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const listRef = React.useRef(null);

  // Build a compact context string from the topic so answers stay grounded.
  const buildContext = () => {
    const lessonText = (topic.lesson || []).map((s) => s.h + ": " + s.p.join(" ")).join("\n");
    const formulas = (topic.keyFormulas || []).join("; ");
    const plain = topic.plain ? topic.plain.plain : "";
    const w1 = topic.worked ? topic.worked.title + " — " + topic.worked.takeaway : "";
    const w2 = topic.worked2 ? topic.worked2.title + " — " + topic.worked2.takeaway : "";
    return `TOPIC: ${topic.name}\n\nLESSON:\n${lessonText}\n\nKEY FORMULAS: ${formulas}\n\nPLAIN-ENGLISH SUMMARY: ${plain}\n\nWORKED EXAMPLES: ${w1} | ${w2}`;
  };

  const send = async (question) => {
    const q = (question != null ? question : input).trim();
    if (!q || loading) return;
    setError(null);
    const newMsgs = [...messages, { role: "user", content: q }];
    setMessages(newMsgs);
    setInput("");
    setLoading(true);
    try {
      const system = `You are a patient, expert Intermediate Accounting II tutor helping a student who is studying the topic "${topic.name}". Use the topic material below as your primary reference and keep your answers consistent with it.\n\n${buildContext()}\n\nGuidelines: Give direct, clear answers with brief explanations. Be accurate above all — Intermediate Accounting II is exam material, so never guess at a number or rule; if something is genuinely ambiguous or outside this topic, say so plainly. Use plain language first, then the precise accounting terms. Keep answers concise (a few short paragraphs at most) unless asked to go deep. Use small worked numbers when they help. Do not invent facts about the student's specific course or exam.`;
      const apiMessages = newMsgs.map((m) => ({ role: m.role, content: m.content }));
      const response = await fetch("/api/tutor", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ system, messages: apiMessages }),
      });
      if (!response.ok) throw new Error("Tutor request failed");
      const data = await response.json();
      const text = (data.content || []).filter((c) => c.type === "text").map((c) => c.text).join("\n").trim();
      setMessages((m) => [...m, { role: "assistant", content: text || "Sorry — I couldn't generate a response. Try rephrasing?" }]);
    } catch (e) {
      setError("Couldn't reach the tutor just now. Check your connection and try again.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { if (listRef.current) listRef.current.scrollTop = listRef.current.scrollHeight; }, [messages, loading]);

  const starters = [
    "Explain this topic in a different way",
    "What's the most common mistake here?",
    "Give me a tricky example and walk through it",
  ];

  return (
    <div style={{ background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, boxShadow: T.shadowSm, overflow: "hidden" }}>
      <div style={{ padding: "16px 20px", borderBottom: `1px solid ${T.lineSoft}`, display: "flex", alignItems: "center", gap: 10 }}>
        <span style={{ width: 34, height: 34, borderRadius: 9, background: `linear-gradient(135deg, ${T.brand}, ${T.brandDeep})`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 17 }}>🎓</span>
        <div>
          <div style={{ fontSize: 15, fontWeight: 600, color: T.ink }}>Ask the tutor</div>
          <div style={{ fontSize: 12.5, color: T.inkFaint }}>Grounded in this topic · answers may occasionally need verifying</div>
        </div>
      </div>

      <div ref={listRef} style={{ maxHeight: 440, overflowY: "auto", padding: 20, display: "flex", flexDirection: "column", gap: 14 }}>
        {messages.length === 0 && (
          <div style={{ textAlign: "center", padding: "10px 0 4px" }}>
            <p style={{ fontSize: 14, color: T.inkSoft, lineHeight: 1.6, margin: "0 0 16px" }}>Stuck on something in <strong style={{ color: T.ink }}>{topic.name}</strong>? Ask anything — or start with one of these:</p>
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {starters.map((s, i) => (
                <button key={i} onClick={() => send(s)} style={{ padding: "10px 14px", borderRadius: T.radiusSm, border: `1px solid ${T.line}`, background: T.surfaceAlt, color: T.inkSoft, fontSize: 13.5, cursor: "pointer", fontFamily: T.font, textAlign: "left", transition: "all 160ms ease" }}
                  onMouseEnter={(e) => { e.currentTarget.style.borderColor = T.brand; e.currentTarget.style.color = T.ink; }}
                  onMouseLeave={(e) => { e.currentTarget.style.borderColor = T.line; e.currentTarget.style.color = T.inkSoft; }}>{s}</button>
              ))}
            </div>
          </div>
        )}
        {messages.map((m, i) => (
          <div key={i} style={{ display: "flex", justifyContent: m.role === "user" ? "flex-end" : "flex-start" }}>
            <div style={{ maxWidth: "85%", padding: "11px 15px", borderRadius: 14, fontSize: 14.5, lineHeight: 1.65, whiteSpace: "pre-wrap",
              background: m.role === "user" ? T.brand : T.surfaceAlt,
              color: m.role === "user" ? "#0E0F0D" : T.ink,
              borderBottomRightRadius: m.role === "user" ? 4 : 14, borderBottomLeftRadius: m.role === "user" ? 14 : 4 }}>
              {m.content}
            </div>
          </div>
        ))}
        {loading && (
          <div style={{ display: "flex", justifyContent: "flex-start" }}>
            <div style={{ padding: "11px 15px", borderRadius: 14, background: T.surfaceAlt, color: T.inkFaint, fontSize: 14 }}>
              <span className="tutorDots">Thinking</span>
            </div>
          </div>
        )}
        {error && <div style={{ fontSize: 13, color: T.rose, background: T.roseSoft, padding: "10px 14px", borderRadius: 10 }}>{error}</div>}
      </div>

      <div style={{ padding: 14, borderTop: `1px solid ${T.lineSoft}`, display: "flex", gap: 10 }}>
        <input value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); send(); } }}
          placeholder={`Ask about ${topic.name}…`} disabled={loading}
          style={{ flex: 1, padding: "11px 14px", borderRadius: T.radiusSm, border: `1.5px solid ${T.line}`, background: T.bg, color: T.ink, fontSize: 14.5, fontFamily: T.font, outline: "none" }} />
        <button onClick={() => send()} disabled={loading || !input.trim()} style={{ padding: "11px 20px", borderRadius: T.radiusSm, border: "none", background: loading || !input.trim() ? T.line : T.brand, color: loading || !input.trim() ? T.inkFaint : "#0E0F0D", fontSize: 14.5, fontWeight: 600, cursor: loading || !input.trim() ? "default" : "pointer", fontFamily: T.font }}>Send</button>
      </div>
    </div>
  );
}

export default function App() {
  const TOPICS = TOPICS_DATA;
  const byId = useMemo(() => Object.fromEntries(TOPICS.map((t) => [t.id, t])), [TOPICS]);
  const [view, setView] = useState("home"); // home | path | topic | practice | calc | exam | progress
  const [activeId, setActiveId] = useState(PATH[0].id);
  const [tab, setTab] = useState("learn"); // learn | practice (within topic)
  const [progress, dispatch] = useReducer(progressReducer, {});
  const [storageReady, setStorageReady] = useState(false);
  const [progressSaved, setProgressSaved] = useState(false);
  const [practiceQ, setPracticeQ] = useState(null);
  const [practiceN, setPracticeN] = useState(0);
  const [bookmarkOnly, setBookmarkOnly] = useState(false);
  // Mock exam state
  const [examState, setExamState] = useState("idle"); // idle | running | done
  const [examQs, setExamQs] = useState([]);
  const [examAnswers, setExamAnswers] = useState({});
  const [examIdx, setExamIdx] = useState(0);
  const [examTimeLeft, setExamTimeLeft] = useState(0);
  const scrollRef = React.useRef(null);

  // Load saved progress once on mount (persists across sessions via localStorage)
  useEffect(() => {
    try {
      const raw = typeof window !== "undefined" ? window.localStorage.getItem("ia2_progress") : null;
      if (raw) {
        const saved = JSON.parse(raw);
        if (saved && typeof saved === "object") dispatch({ type: "hydrate", payload: saved });
      }
    } catch (e) { /* no saved progress yet — fine */ }
    setStorageReady(true);
  }, []);

  // Save progress whenever it changes (after initial load)
  useEffect(() => {
    if (!storageReady) return;
    try {
      if (typeof window !== "undefined") {
        window.localStorage.setItem("ia2_progress", JSON.stringify(progress));
        setProgressSaved(true);
        setTimeout(() => setProgressSaved(false), 1500);
      }
    } catch (e) { /* storage unavailable — progress stays in-session only */ }
  }, [progress, storageReady]);

  const active = byId[activeId];
  const pathIndex = PATH.findIndex((p) => p.id === activeId);

  // scroll to top on view/topic change
  useEffect(() => { if (scrollRef.current) scrollRef.current.scrollTo({ top: 0, behavior: "smooth" }); }, [activeId, view, tab]);

  const allQ = useMemo(() => {
    const out = [];
    TOPICS.forEach((t) => {
      t.bank.forEach((q, i) => out.push({ ...q, topicId: t.id, topicName: t.name, key: `${t.id}-${i}` }));
      if (t.advanced && Array.isArray(t.advanced.bank)) {
        t.advanced.bank.forEach((q, i) => out.push({ ...q, topicId: t.id, topicName: t.name, key: `${t.id}-adv-${i}`, adv: true }));
      }
    });
    return out;
  }, [TOPICS]);

  // Questions available to serve: advanced questions only appear once that topic's advanced tier is unlocked.
  const servableQ = () => allQ.filter((q) => !q.adv || advancedProgress(q.topicId).unlocked);

  // Mock exam countdown timer
  useEffect(() => {
    if (examState !== "running") return;
    if (examTimeLeft <= 0) { setExamState("done"); return; }
    const id = setTimeout(() => setExamTimeLeft((s) => s - 1), 1000);
    return () => clearTimeout(id);
  }, [examState, examTimeLeft]);

  // Log exam result to history exactly once when it finishes
  const examLogged = React.useRef(false);
  useEffect(() => {
    if (examState === "running") { examLogged.current = false; return; }
    if (examState === "done" && !examLogged.current && examQs.length) {
      examLogged.current = true;
      const correct = examQs.filter((q, i) => examAnswers[i] === q.answer).length;
      const pct = Math.round((correct / examQs.length) * 100);
      const byTopic = {};
      examQs.forEach((q, i) => {
        const t = byTopic[q.topicId] || { name: q.topicName, correct: 0, total: 0 };
        t.total += 1;
        if (examAnswers[i] === q.answer) t.correct += 1;
        byTopic[q.topicId] = t;
      });
      dispatch({ type: "logExam", correct, total: examQs.length, pct, byTopic });
    }
  }, [examState, examQs, examAnswers]);

  const startExam = (count, minutes) => {
    // Pull a balanced mix across topics, shuffle (advanced questions included only where unlocked)
    const shuffled = [...servableQ()].sort(() => Math.random() - 0.5).slice(0, count);
    setExamQs(shuffled);
    setExamAnswers({});
    setExamIdx(0);
    setExamTimeLeft(minutes * 60);
    setExamState("running");
  };

  // Only entries that are real question records (have a topicId and seen count).
  const questionEntries = () => Object.entries(progress).filter(([k, s]) => !k.startsWith("__") && s && typeof s === "object" && "seen" in s);

  const topicAcc = (tid) => {
    const e = questionEntries().map(([, s]) => s).filter((s) => s.topicId === tid);
    if (!e.length) return null;
    const seen = e.reduce((a, s) => a + s.seen, 0);
    const correct = e.reduce((a, s) => a + s.correct, 0);
    return seen ? correct / seen : null;
  };
  const topicSeen = (tid) => questionEntries().map(([, s]) => s).filter((s) => s.topicId === tid).reduce((a, s) => a + s.seen, 0);

  // ---- Advanced tier unlock: earned by demonstrating mastery on a topic ----
  // Unlocks when the user has answered >= 8 distinct questions on the topic with >= 80% accuracy.
  const ADV_MIN_QUESTIONS = 8;
  const ADV_MIN_ACCURACY = 0.8;
  const advancedProgress = (tid) => {
    const e = questionEntries().filter(([, s]) => s.topicId === tid);
    const distinct = e.length; // distinct questions attempted
    const seen = e.reduce((a, [, s]) => a + s.seen, 0);
    const correct = e.reduce((a, [, s]) => a + s.correct, 0);
    const acc = seen ? correct / seen : 0;
    const unlocked = distinct >= ADV_MIN_QUESTIONS && acc >= ADV_MIN_ACCURACY;
    return { distinct, acc, unlocked, needQuestions: Math.max(0, ADV_MIN_QUESTIONS - distinct) };
  };

  const overallSeen = questionEntries().reduce((a, [, s]) => a + s.seen, 0);
  const overallCorrect = questionEntries().reduce((a, [, s]) => a + s.correct, 0);
  const overallPct = overallSeen ? (overallCorrect / overallSeen) * 100 : 0;
  const topicsStarted = PATH.filter((p) => topicSeen(p.id) > 0).length;

  // ---- Spaced review: what's worth revisiting today ----
  // A topic's "review urgency" rises with weak accuracy and with time since last touched.
  const DAY = 86400000;
  const topicReview = (tid) => {
    const entries = questionEntries().map(([, s]) => s).filter((s) => s.topicId === tid && s.seen > 0);
    if (!entries.length) return null;
    const seen = entries.reduce((a, s) => a + s.seen, 0);
    const correct = entries.reduce((a, s) => a + s.correct, 0);
    const acc = seen ? correct / seen : 0;
    const lastSeen = Math.max(...entries.map((s) => s.lastSeen || 0));
    const daysSince = lastSeen ? (Date.now() - lastSeen) / DAY : 999;
    const missedHere = entries.filter((s) => s.missed).length;
    // Recommended interval shrinks when accuracy is low: strong recall earns a longer gap.
    const interval = acc >= 0.9 ? 7 : acc >= 0.75 ? 3 : acc >= 0.5 ? 1 : 0.5;
    const due = daysSince >= interval;
    // urgency score for sorting
    const urgency = (1 - acc) * 2 + Math.min(daysSince / Math.max(interval, 0.5), 3) + missedHere * 0.2;
    return { acc, daysSince, lastSeen, missedHere, interval, due, urgency, seen };
  };
  const reviewQueue = () => PATH.map((p) => ({ id: p.id, name: byId[p.id].name, ...(topicReview(p.id) || {}) })).filter((r) => r.seen > 0 && r.due).sort((a, b) => b.urgency - a.urgency);
  const bookmarked = () => allQ.filter((q) => progress[q.key]?.bookmarked);
  const examHistory = () => (Array.isArray(progress.__examHistory) ? progress.__examHistory : []);
  const missedCount = allQ.filter((q) => progress[q.key]?.missed).length;

  const record = (q, correct) => dispatch({ type: "answer", key: q.key, topicId: q.topicId, correct });

  const pickAdaptive = () => {
    const pool0 = servableQ();
    if (bookmarkOnly) {
      const marks = pool0.filter((q) => progress[q.key]?.bookmarked);
      if (marks.length) return marks[Math.floor(Math.random() * marks.length)];
      setBookmarkOnly(false); // none left — fall back to normal
    }
    const missed = pool0.filter((q) => progress[q.key]?.missed);
    const unseen = pool0.filter((q) => !progress[q.key]);
    let pool;
    if (missed.length) pool = missed;
    else if (unseen.length) {
      const weakUnseen = unseen.filter((q) => { const a = topicAcc(q.topicId); return a !== null && a < 0.7; });
      pool = weakUnseen.length ? weakUnseen : unseen;
    } else pool = pool0;
    return pool[Math.floor(Math.random() * pool.length)];
  };

  // The next-up recommendation for the guided path
  const nextUp = useMemo(() => {
    for (const p of PATH) {
      const acc = topicAcc(p.id);
      const seen = topicSeen(p.id);
      if (seen === 0 || (acc !== null && acc < 0.8)) return p.id;
    }
    return PATH[0].id;
  }, [progress]);

  const goTopic = (id) => { setActiveId(id); setTab("learn"); setView("topic"); };
  const goNextInPath = () => {
    const idx = PATH.findIndex((p) => p.id === activeId);
    const next = PATH[(idx + 1) % PATH.length];
    setActiveId(next.id); setTab("learn"); setView("topic");
  };
  const goPrevInPath = () => {
    const idx = PATH.findIndex((p) => p.id === activeId);
    const prev = PATH[(idx - 1 + PATH.length) % PATH.length];
    setActiveId(prev.id); setTab("learn"); setView("topic");
  };

  // ---------- Shared chrome ----------
  const NavButton = ({ id, label, icon }) => {
    const on = view === id;
    return (
      <button onClick={() => { setView(id); if (id === "practice" && !practiceQ) setPracticeQ(pickAdaptive()); }}
        style={{ display: "flex", alignItems: "center", gap: 8, padding: "9px 16px", borderRadius: 999, border: "none", background: on ? T.brand : "transparent", color: on ? "#0E0F0D" : T.inkSoft, fontSize: 14, fontWeight: on ? 600 : 500, cursor: "pointer", transition: "all 200ms ease", fontFamily: T.font }}
        onMouseEnter={(e) => { if (!on) e.currentTarget.style.background = T.surfaceAlt; }}
        onMouseLeave={(e) => { if (!on) e.currentTarget.style.background = "transparent"; }}>
        <span style={{ fontSize: 15 }}>{icon}</span>{label}
      </button>
    );
  };

  const Header = () => (
    <header style={{ position: "sticky", top: 0, zIndex: 20, background: "rgba(14,15,13,0.8)", backdropFilter: "saturate(180%) blur(12px)", WebkitBackdropFilter: "saturate(180%) blur(12px)", borderBottom: `1px solid ${T.line}` }}>
      <div style={{ maxWidth: 980, margin: "0 auto", padding: "12px 24px", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 16, flexWrap: "wrap" }}>
        <button onClick={() => setView("home")} style={{ display: "flex", alignItems: "center", gap: 11, background: "none", border: "none", cursor: "pointer", padding: 0 }}>
          <span style={{ width: 34, height: 34, borderRadius: 9, background: `linear-gradient(135deg, ${T.brand}, ${T.brandDeep})`, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700, fontSize: 16, boxShadow: T.shadowSm, fontFamily: T.serif }}>I</span>
          <span style={{ textAlign: "left" }}>
            <span style={{ display: "block", fontSize: 15, fontWeight: 700, color: T.ink, lineHeight: 1.1, letterSpacing: "-0.01em" }}>Intermediate II</span>
            <span style={{ display: "block", fontSize: 11.5, color: T.inkFaint, fontWeight: 500 }}>Mastery Course</span>
          </span>
        </button>
        <nav style={{ display: "flex", alignItems: "center", gap: 4, background: T.surface, padding: 4, borderRadius: 999, border: `1px solid ${T.line}`, boxShadow: T.shadowSm }}>
          <NavButton id="home" label="Home" icon="⌂" />
          <NavButton id="path" label="Path" icon="◆" />
          <NavButton id="practice" label="Practice" icon="◎" />
          <NavButton id="calc" label="Tools" icon="▣" />
          <NavButton id="exam" label="Mock Exam" icon="◈" />
          <NavButton id="progress" label="Progress" icon="◐" />
        </nav>
      </div>
    </header>
  );

  // ---------- PATH (home / guided curriculum) ----------
  const renderHome = () => {
    const sections = [
      { id: "path", icon: "◆", emoji: "🗺️", name: "Path", desc: "The nine topics in the order to learn them. Each opens into lessons, a plain-English explainer, a lecture, study aids, worked examples, and a live tutor." },
      { id: "practice", icon: "◎", emoji: "✍️", name: "Practice", desc: "Adaptive questions that serve you what you got wrong and what you haven't mastered yet. Bookmark tricky ones to revisit." },
      { id: "calc", icon: "▣", emoji: "🧮", name: "Tools", desc: "Live calculators for bonds, leases, and deferred tax. Change any input and watch the full schedule recompute." },
      { id: "exam", icon: "◈", emoji: "⏱️", name: "Mock Exam", desc: "Timed, mixed-topic exams that simulate test conditions. No explanations until you submit — then a full review." },
      { id: "progress", icon: "◐", emoji: "📊", name: "Progress", desc: "Your accuracy by topic, what's due for review today, and your mock-exam trend over time." },
    ];
    return (
      <div style={{ maxWidth: 980, margin: "0 auto", padding: "32px 24px 80px" }}>
        {/* Welcome hero */}
        <div style={{ background: "linear-gradient(135deg, #0C3D2C 0%, #145740 55%, #1E7A58 100%)", borderRadius: T.radiusLg, padding: "40px 36px", color: "#fff", boxShadow: T.shadowLg, position: "relative", overflow: "hidden", border: "1px solid rgba(63,185,133,0.25)" }}>
          <div style={{ position: "absolute", right: -50, top: -50, width: 220, height: 220, borderRadius: "50%", background: "rgba(255,255,255,0.05)" }} />
          <div style={{ position: "absolute", right: 80, bottom: -70, width: 170, height: 170, borderRadius: "50%", background: "rgba(255,255,255,0.04)" }} />
          <div style={{ position: "relative" }}>
            <div style={{ fontSize: 12.5, fontWeight: 600, letterSpacing: "0.06em", textTransform: "uppercase", opacity: 0.85 }}>Welcome</div>
            <h1 style={{ margin: "10px 0 0", fontSize: 32, fontWeight: 600, lineHeight: 1.12, fontFamily: T.serif, letterSpacing: "-0.02em", maxWidth: 600 }}>Master Intermediate Accounting II.</h1>
            <p style={{ margin: "14px 0 0", fontSize: 15.5, lineHeight: 1.65, opacity: 0.92, maxWidth: 540 }}>Nine core topics, taught in the right order and built to make the ideas actually stick — plain-English explainers, worked journal entries, live calculators, adaptive practice, and timed mock exams.</p>
            <div style={{ display: "flex", gap: 12, marginTop: 24, flexWrap: "wrap" }}>
              <button onClick={() => (topicsStarted === 0 ? setView("path") : goTopic(nextUp))} style={{ background: "#fff", color: "#0C3D2C", border: "none", borderRadius: T.radiusSm, padding: "13px 26px", fontSize: 15, fontWeight: 700, cursor: "pointer", boxShadow: T.shadowMd, fontFamily: T.font, transition: "transform 160ms ease" }}
                onMouseEnter={(e) => (e.currentTarget.style.transform = "translateY(-1px)")} onMouseLeave={(e) => (e.currentTarget.style.transform = "translateY(0)")}>
                {topicsStarted === 0 ? "Start learning →" : `Continue: ${byId[nextUp].name} →`}
              </button>
              {topicsStarted > 0 && (
                <button onClick={() => setView("progress")} style={{ background: "rgba(255,255,255,0.12)", color: "#fff", border: "none", borderRadius: T.radiusSm, padding: "13px 22px", fontSize: 15, fontWeight: 600, cursor: "pointer", fontFamily: T.font }}>See my progress</button>
              )}
            </div>
          </div>
        </div>

        {/* What is Intermediate Accounting II — subject orientation for newcomers */}
        <div style={{ marginTop: 30 }}>
          <h2 style={{ margin: "0 0 14px", fontSize: 18, fontWeight: 600, color: T.ink, fontFamily: T.serif }}>New here? Start with this.</h2>
          <div style={{ background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, padding: "24px 26px", boxShadow: T.shadowSm }}>
            <h3 style={{ margin: "0 0 10px", fontSize: 16.5, fontWeight: 600, color: T.ink }}>What is Intermediate Accounting II?</h3>
            <p style={{ margin: "0 0 14px", fontSize: 15, lineHeight: 1.75, color: T.inkSoft }}>
              Intro accounting taught you the basics — debits and credits, the four financial statements, how a transaction becomes an entry. Intermediate Accounting II is where you learn to handle the <strong style={{ color: T.ink }}>hard, real-world items</strong> that sit on a company's books: long-term debt, leases, pensions, income taxes, stockholders' equity, and how all of it flows through to the financial statements. It's the heart of what a CPA actually does, and it's heavily tested on the exam.
            </p>
            <p style={{ margin: "0 0 18px", fontSize: 15, lineHeight: 1.75, color: T.inkSoft }}>
              The thing that trips people up: most of these topics aren't really about memorizing rules — they're about <strong style={{ color: T.ink }}>one or two core ideas reused everywhere</strong>. Once you understand present value (money is worth more today than later), most of the course is the same idea wearing different costumes. That's why the order matters.
            </p>

            <div style={{ display: "flex", flexDirection: "column", gap: 12, marginTop: 6 }}>
              <div style={{ fontSize: 12.5, fontWeight: 700, color: T.inkFaint, letterSpacing: "0.04em", textTransform: "uppercase" }}>What you'll cover, and why it's grouped this way</div>
              {[
                { phase: "Foundations of Liabilities", topics: "Bonds · Leases · Income Taxes · Pensions", why: "The big obligations a company owes. Bonds teach present value and amortization — the engine the other three reuse." },
                { phase: "The Equity Side", topics: "Stockholders' Equity · EPS · Investments", why: "The owners' side of the balance sheet: raising capital, measuring profit per share, and accounting for stakes in other companies." },
                { phase: "Income & Reporting", topics: "Revenue Recognition · Statement of Cash Flows", why: "When you're allowed to call something 'earned,' and how to follow the real cash behind the profit." },
              ].map((g, i) => (
                <div key={i} style={{ display: "flex", gap: 14, alignItems: "flex-start", padding: "14px 16px", background: T.surfaceAlt, borderRadius: T.radiusSm, borderLeft: `3px solid ${T.brand}` }}>
                  <span style={{ flexShrink: 0, fontSize: 12, fontWeight: 700, color: "#0E0F0D", background: T.brand, borderRadius: 999, width: 22, height: 22, display: "flex", alignItems: "center", justifyContent: "center", marginTop: 1 }}>{i + 1}</span>
                  <div>
                    <div style={{ fontSize: 14.5, fontWeight: 600, color: T.ink }}>{g.phase}</div>
                    <div style={{ fontSize: 13, color: T.brandDeep, fontWeight: 500, margin: "2px 0 5px" }}>{g.topics}</div>
                    <p style={{ margin: 0, fontSize: 13.5, lineHeight: 1.6, color: T.inkSoft }}>{g.why}</p>
                  </div>
                </div>
              ))}
            </div>

            <div style={{ marginTop: 18, padding: "14px 16px", background: T.brandTint, borderRadius: T.radiusSm, border: `1px solid ${T.brand}22` }}>
              <p style={{ margin: 0, fontSize: 13.5, lineHeight: 1.65, color: T.inkSoft }}>
                <strong style={{ color: T.brandDeep }}>If you're brand new:</strong> don't jump around. Start at Bonds and go top to bottom — the path is built so each topic leans on the one before it. And read the "In plain English" section of each topic first; it gives you the whole idea in everyday language before the formal accounting terms.
              </p>
            </div>
          </div>
        </div>

        {/* How to use — 3 steps */}
        <div style={{ marginTop: 30 }}>
          <h2 style={{ margin: "0 0 16px", fontSize: 18, fontWeight: 600, color: T.ink, fontFamily: T.serif }}>How to use this</h2>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: 14 }}>
            {[
              { n: "1", t: "Follow the Path", d: "Start at Bonds and work down. The order is deliberate — each topic reuses the one before it. Read the plain-English version first, then the lesson." },
              { n: "2", t: "Practice & test", d: "Drill the question bank, build journal entries yourself, and sit a timed mock exam. Producing answers — not re-reading — is what builds mastery." },
              { n: "3", t: "Review what fades", d: "Check Progress for what's due to revisit. Studying the topics that are slipping, before they're gone, is the highest-value thing you can do." },
            ].map((s) => (
              <div key={s.n} style={{ background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, padding: 20, boxShadow: T.shadowSm }}>
                <span style={{ display: "inline-flex", width: 28, height: 28, borderRadius: 999, background: T.brand, color: "#0E0F0D", alignItems: "center", justifyContent: "center", fontSize: 14, fontWeight: 700, marginBottom: 12 }}>{s.n}</span>
                <div style={{ fontSize: 15, fontWeight: 600, color: T.ink, marginBottom: 5 }}>{s.t}</div>
                <p style={{ margin: 0, fontSize: 13.5, lineHeight: 1.6, color: T.inkSoft }}>{s.d}</p>
              </div>
            ))}
          </div>
        </div>

        {/* What's inside — section guide */}
        <div style={{ marginTop: 32 }}>
          <h2 style={{ margin: "0 0 4px", fontSize: 18, fontWeight: 600, color: T.ink, fontFamily: T.serif }}>What's inside</h2>
          <p style={{ margin: "0 0 16px", fontSize: 13.5, color: T.inkFaint }}>Tap any section below, or use the tabs at the top.</p>
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {sections.map((s) => (
              <button key={s.id} onClick={() => setView(s.id)} style={{ display: "flex", gap: 16, alignItems: "center", textAlign: "left", background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, padding: "16px 18px", cursor: "pointer", transition: "all 180ms ease", fontFamily: T.font, boxShadow: T.shadowSm }}
                onMouseEnter={(e) => { e.currentTarget.style.transform = "translateY(-2px)"; e.currentTarget.style.borderColor = T.brand; }}
                onMouseLeave={(e) => { e.currentTarget.style.transform = "translateY(0)"; e.currentTarget.style.borderColor = T.line; }}>
                <div style={{ flexShrink: 0, width: 44, height: 44, borderRadius: 12, background: T.surfaceAlt, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20 }}>{s.emoji}</div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 15.5, fontWeight: 600, color: T.ink }}>{s.name}</div>
                  <p style={{ margin: "3px 0 0", fontSize: 13, lineHeight: 1.5, color: T.inkSoft }}>{s.desc}</p>
                </div>
                <span style={{ flexShrink: 0, color: T.inkFaint, fontSize: 18 }}>→</span>
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  };

  const renderPath = () => {
    const phases = [...new Set(PATH.map((p) => p.phase))];
    return (
      <div style={{ maxWidth: 980, margin: "0 auto", padding: "32px 24px 80px" }}>
        {/* Hero */}
        <div style={{ background: "linear-gradient(135deg, #0C3D2C 0%, #145740 55%, #1E7A58 100%)", borderRadius: T.radiusLg, padding: "34px 34px", color: "#fff", boxShadow: T.shadowLg, position: "relative", overflow: "hidden", border: "1px solid rgba(63,185,133,0.25)" }}>
          <div style={{ position: "absolute", right: -40, top: -40, width: 200, height: 200, borderRadius: "50%", background: "rgba(255,255,255,0.05)" }} />
          <div style={{ position: "absolute", right: 60, bottom: -60, width: 160, height: 160, borderRadius: "50%", background: "rgba(255,255,255,0.04)" }} />
          <div style={{ position: "relative" }}>
            <div style={{ fontSize: 12.5, fontWeight: 600, letterSpacing: "0.06em", textTransform: "uppercase", opacity: 0.85 }}>Your guided path</div>
            <h1 style={{ margin: "10px 0 0", fontSize: 30, fontWeight: 600, lineHeight: 1.15, fontFamily: T.serif, letterSpacing: "-0.02em", maxWidth: 560 }}>Learn Intermediate Accounting II in the right order.</h1>
            <p style={{ margin: "12px 0 0", fontSize: 15.5, lineHeight: 1.6, opacity: 0.92, maxWidth: 520 }}>Nine topics, sequenced so each one builds on the last. Start at the top and follow the path — every topic has lessons, two worked examples, a question bank, and practice problems.</p>
            <div style={{ display: "flex", gap: 12, marginTop: 22, flexWrap: "wrap" }}>
              <button onClick={() => goTopic(nextUp)} style={{ background: "#fff", color: "#0C3D2C", border: "none", borderRadius: T.radiusSm, padding: "13px 24px", fontSize: 15, fontWeight: 700, cursor: "pointer", boxShadow: T.shadowMd, fontFamily: T.font, transition: "transform 160ms ease" }}
                onMouseEnter={(e) => (e.currentTarget.style.transform = "translateY(-1px)")} onMouseLeave={(e) => (e.currentTarget.style.transform = "translateY(0)")}>
                {topicsStarted === 0 ? "Begin with Bonds →" : `Continue: ${byId[nextUp].name} →`}
              </button>
              <div style={{ display: "flex", alignItems: "center", gap: 14, padding: "8px 18px", background: "rgba(255,255,255,0.1)", borderRadius: T.radiusSm }}>
                <div><div style={{ fontSize: 20, fontWeight: 700, lineHeight: 1 }}>{topicsStarted}/9</div><div style={{ fontSize: 11.5, opacity: 0.8 }}>started</div></div>
                <div style={{ width: 1, height: 28, background: "rgba(255,255,255,0.2)" }} />
                <div><div style={{ fontSize: 20, fontWeight: 700, lineHeight: 1 }}>{Math.round(overallPct)}%</div><div style={{ fontSize: 11.5, opacity: 0.8 }}>accuracy</div></div>
              </div>
            </div>
          </div>
        </div>

        {/* Where to start callout */}
        <div style={{ marginTop: 26, display: "flex", gap: 14, alignItems: "flex-start", padding: "18px 20px", background: T.goldSoft, borderRadius: T.radius, border: `1px solid ${T.gold}22` }}>
          <span style={{ fontSize: 20, flexShrink: 0 }}>🧭</span>
          <div>
            <div style={{ fontSize: 14.5, fontWeight: 700, color: T.ink }}>New to the material? Start with Bonds.</div>
            <p style={{ margin: "4px 0 0", fontSize: 13.5, lineHeight: 1.6, color: T.inkSoft }}>Bonds teach present value and effective-interest amortization — the engine that leases, pensions, and income taxes all reuse. Nail the first topic and the next three will feel familiar. Work top-to-bottom; the order is deliberate.</p>
          </div>
        </div>

        {/* Phased path */}
        {phases.map((phase, pi) => (
          <div key={phase} style={{ marginTop: 34 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 16 }}>
              <span style={{ fontSize: 12.5, fontWeight: 700, color: "#0E0F0D", background: T.brand, borderRadius: 999, width: 24, height: 24, display: "flex", alignItems: "center", justifyContent: "center" }}>{pi + 1}</span>
              <h2 style={{ margin: 0, fontSize: 17, fontWeight: 600, color: T.ink, fontFamily: T.serif }}>{phase}</h2>
              <div style={{ flex: 1, height: 1, background: T.line }} />
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {PATH.filter((p) => p.phase === phase).map((p) => {
                const t = byId[p.id];
                const globalIdx = PATH.findIndex((x) => x.id === p.id);
                const acc = topicAcc(p.id);
                const seen = topicSeen(p.id);
                const isNext = p.id === nextUp;
                const done = acc !== null && acc >= 0.8 && seen >= t.bank.length / 2;
                return (
                  <button key={p.id} onClick={() => goTopic(p.id)}
                    style={{ display: "flex", gap: 18, alignItems: "center", textAlign: "left", background: T.surface, border: `1.5px solid ${isNext ? T.brand : T.line}`, borderRadius: T.radius, padding: "18px 20px", cursor: "pointer", transition: "all 200ms ease", boxShadow: isNext ? T.shadowMd : T.shadowSm, position: "relative", fontFamily: T.font }}
                    onMouseEnter={(e) => { e.currentTarget.style.transform = "translateY(-2px)"; e.currentTarget.style.boxShadow = T.shadowMd; }}
                    onMouseLeave={(e) => { e.currentTarget.style.transform = "translateY(0)"; e.currentTarget.style.boxShadow = isNext ? T.shadowMd : T.shadowSm; }}>
                    <div style={{ flexShrink: 0, width: 46, height: 46, borderRadius: 13, background: done ? T.brandSoft : T.surfaceAlt, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 22 }}>{done ? "✓" : t.icon}</div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
                        <span style={{ fontSize: 12, fontWeight: 700, color: T.inkFaint }}>{String(globalIdx + 1).padStart(2, "0")}</span>
                        <span style={{ fontSize: 16, fontWeight: 600, color: T.ink }}>{t.name}</span>
                        {isNext && <Pill color={T.brandDeep} bg={T.brandSoft}>Next up</Pill>}
                        {done && <Pill color={T.brandDeep} bg={T.brandSoft}>Mastered</Pill>}
                      </div>
                      <p style={{ margin: "5px 0 0", fontSize: 13, lineHeight: 1.5, color: T.inkSoft, maxWidth: 620 }}>{t.overview}</p>
                      {seen > 0 && (
                        <div style={{ display: "flex", alignItems: "center", gap: 10, marginTop: 10 }}>
                          <div style={{ flex: 1, maxWidth: 180 }}><ProgressBar value={(acc || 0) * 100} /></div>
                          <span style={{ fontSize: 12, color: T.inkFaint, fontWeight: 500 }}>{Math.round((acc || 0) * 100)}% · {seen} answered</span>
                        </div>
                      )}
                    </div>
                    <span style={{ flexShrink: 0, color: isNext ? T.brand : T.inkFaint, fontSize: 20 }}>→</span>
                  </button>
                );
              })}
            </div>
          </div>
        ))}
      </div>
    );
  };

  // ---------- TOPIC ----------
  const renderTopic = () => {
    const t = active;
    const acc = topicAcc(t.id);
    const pathStep = PATH[pathIndex];
    return (
      <div style={{ maxWidth: 760, margin: "0 auto", padding: "28px 24px 80px" }}>
        {/* breadcrumb + position */}
        <div style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, color: T.inkFaint, marginBottom: 18 }}>
          <button onClick={() => setView("path")} style={{ background: "none", border: "none", color: T.brand, cursor: "pointer", fontWeight: 600, padding: 0, fontFamily: T.font, fontSize: 13 }}>Path</button>
          <span>/</span>
          <span>{pathStep.phase}</span>
          <span>/</span>
          <span style={{ color: T.inkSoft, fontWeight: 600 }}>Topic {pathIndex + 1} of {PATH.length}</span>
        </div>

        {/* title card */}
        <div style={{ background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radiusLg, padding: 26, boxShadow: T.shadowSm }}>
          <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
            <div style={{ width: 56, height: 56, borderRadius: 15, background: T.brandTint, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 28, flexShrink: 0 }}>{t.icon}</div>
            <div style={{ flex: 1 }}>
              <h1 style={{ margin: 0, fontSize: 25, fontWeight: 600, color: T.ink, fontFamily: T.serif, letterSpacing: "-0.02em", lineHeight: 1.1 }}>{t.name}</h1>
              {acc !== null && <div style={{ marginTop: 8, display: "flex", alignItems: "center", gap: 10 }}><div style={{ width: 140 }}><ProgressBar value={acc * 100} /></div><span style={{ fontSize: 12.5, color: T.inkFaint }}>{Math.round(acc * 100)}% accuracy</span></div>}
            </div>
          </div>
          <p style={{ margin: "16px 0 0", fontSize: 15, lineHeight: 1.6, color: T.inkSoft }}>{t.overview}</p>
          {/* why here in the path */}
          <div style={{ marginTop: 16, padding: "13px 15px", background: T.surfaceAlt, borderRadius: T.radiusSm, fontSize: 13.5, lineHeight: 1.6, color: T.inkSoft }}>
            <span style={{ fontWeight: 700, color: T.brand }}>Why this is topic {pathIndex + 1}: </span>{pathStep.why}
          </div>
        </div>

        {/* tabs */}
        <div style={{ display: "flex", gap: 4, marginTop: 22, background: T.surface, padding: 4, borderRadius: 999, border: `1px solid ${T.line}`, width: "fit-content", boxShadow: T.shadowSm }}>
          {[["learn", "Learn"], ["practice", "Practice"]].map(([id, label]) => (
            <button key={id} onClick={() => setTab(id)} style={{ padding: "8px 22px", borderRadius: 999, border: "none", background: tab === id ? T.brand : "transparent", color: tab === id ? "#0E0F0D" : T.inkSoft, fontSize: 14, fontWeight: tab === id ? 600 : 500, cursor: "pointer", transition: "all 180ms ease", fontFamily: T.font }}>{label}</button>
          ))}
        </div>

        {tab === "learn" ? (
          <>
            {/* In plain English — Feynman layer, shown first */}
            {t.plain && (
              <div style={{ marginTop: 26 }}>
                <SectionHead kicker="In plain English" title="The whole idea, no jargon" sub="If it can't be said simply and still be true, it isn't really understood. Read this first, then the rigorous version below." />
                <PlainEnglish plain={t.plain} />
              </div>
            )}

            {/* Lecture mode — narrated walk-through */}
            {t.lecture && (
              <div style={{ marginTop: 26 }}>
                <SectionHead kicker="Lecture" title="The narrated walk-through" sub="A teacher talking you through the topic start to finish — why each piece leads to the next." />
                <LectureMode lecture={t.lecture} topicName={t.name} />
              </div>
            )}

            {/* Lesson */}
            <div style={{ marginTop: 26 }}>
              <SectionHead kicker="Lesson" title="The reasoning, from the ground up" />
              <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                {t.lesson.map((sec, i) => (
                  <div key={i} style={{ background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, padding: 22, boxShadow: T.shadowSm }}>
                    <h3 style={{ margin: 0, fontSize: 16.5, fontWeight: 600, color: T.ink }}>{sec.h}</h3>
                    {sec.p.map((para, j) => <p key={j} style={{ margin: "10px 0 0", fontSize: 14.5, lineHeight: 1.7, color: T.inkSoft }}>{para}</p>)}
                  </div>
                ))}
              </div>
            </div>

            {/* Formulas */}
            <div style={{ marginTop: 22 }}>
              <div style={{ background: "#0A0B09", border: `1px solid ${T.line}`, borderRadius: T.radius, padding: 22 }}>
                <h3 style={{ margin: "0 0 12px", fontSize: 13, fontWeight: 700, letterSpacing: "0.05em", textTransform: "uppercase", color: T.brandDeep }}>Key formulas</h3>
                <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                  {t.keyFormulas.map((f, i) => (
                    <div key={i} style={{ fontSize: 13.5, lineHeight: 1.5, color: T.ink, fontFamily: "ui-monospace, 'SF Mono', Menlo, monospace", padding: "10px 14px", background: "rgba(63,185,133,0.08)", borderRadius: 9, borderLeft: `3px solid ${T.brand}` }}>{f}</div>
                  ))}
                </div>
              </div>
            </div>

            {/* Study aids: mnemonics, watch-outs, cheat code */}
            {t.aids && (
              <div style={{ marginTop: 26 }}>
                <SectionHead kicker="Study aids" title="Mnemonics, traps & the cheat code" sub="The memory hooks and one mental shortcut that make this topic click." />
                <StudyAids aids={t.aids} />
              </div>
            )}

            {/* Worked examples */}
            <div style={{ marginTop: 26 }}>
              <SectionHead kicker="Worked example" title="See it solved, step by step" sub="Read each step and the reasoning beneath it. Then try to reproduce the logic before moving on." />
              <WorkedBlock worked={t.worked} entries={t.entries ? t.entries.w1 : []} comptable={t.comptable ? t.comptable.w1 : null} />
            </div>
            {t.worked2 && (
              <div style={{ marginTop: 16 }}>
                <SectionHead kicker="Worked example 2" title="The same idea, a different angle" />
                <WorkedBlock worked={t.worked2} entries={t.entries ? t.entries.w2 : []} comptable={t.comptable ? t.comptable.w2 : null} />
              </div>
            )}

            {t.worked3 && (
              <div style={{ marginTop: 16 }}>
                <SectionHead kicker="Worked example 3" title="Going deeper" />
                <WorkedBlock worked={t.worked3} entries={t.entries ? t.entries.w3 : []} comptable={null} />
              </div>
            )}

            {/* CTA to practice */}
            <div style={{ marginTop: 26, padding: "22px 24px", background: T.brandTint, border: `1px solid ${T.brand}33`, borderRadius: T.radius, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 16, flexWrap: "wrap" }}>
              <div>
                <div style={{ fontSize: 16, fontWeight: 600, color: T.brandDeep }}>Ready to test yourself?</div>
                <div style={{ fontSize: 13.5, color: T.inkSoft, marginTop: 3 }}>{t.bank.length} questions and {t.practice.length} practice problems await.</div>
              </div>
              <button onClick={() => setTab("practice")} style={{ background: T.brand, color: "#0E0F0D", border: "none", borderRadius: T.radiusSm, padding: "12px 24px", fontSize: 14.5, fontWeight: 600, cursor: "pointer", boxShadow: T.shadowSm, fontFamily: T.font }}>Go to practice →</button>
            </div>

            {/* Advanced tier — unlocked by mastery */}
            {t.advanced && (() => {
              const ap = advancedProgress(t.id);
              return (
                <div style={{ marginTop: 30 }}>
                  <SectionHead kicker="Advanced tier" title={ap.unlocked ? "Unlocked — go deeper" : "Locked — earn it"} sub={ap.unlocked ? "You've shown mastery of the core. Here's the harder material." : "Master the core first; this unlocks when you've earned it."} />
                  {ap.unlocked ? (
                    <div>
                      <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "12px 16px", background: T.brandSoft, border: `1px solid ${T.brand}44`, borderRadius: T.radiusSm, marginBottom: 16 }}>
                        <span style={{ fontSize: 18 }}>🔓</span>
                        <span style={{ fontSize: 13.5, color: T.brandDeep, fontWeight: 600 }}>Advanced tier unlocked. {t.advanced.intro}</span>
                      </div>
                      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                        {t.advanced.lesson.map((sec, i) => (
                          <div key={i} style={{ background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, padding: 22, boxShadow: T.shadowSm }}>
                            <h3 style={{ margin: "0 0 10px", fontSize: 16.5, fontWeight: 600, color: T.ink, fontFamily: T.serif }}>{sec.h}</h3>
                            {sec.p.map((para, j) => (
                              <p key={j} style={{ margin: j === 0 ? 0 : "10px 0 0", fontSize: 14.5, lineHeight: 1.7, color: T.inkSoft }}>{para}</p>
                            ))}
                          </div>
                        ))}
                      </div>
                      <div style={{ marginTop: 14, fontSize: 13.5, color: T.inkSoft }}>The advanced questions are mixed into this topic's practice and the mock exam now that you've unlocked them.</div>
                    </div>
                  ) : (
                    <div style={{ background: T.surface, border: `1px dashed ${T.line}`, borderRadius: T.radius, padding: 24, textAlign: "center" }}>
                      <div style={{ fontSize: 30, marginBottom: 10, opacity: 0.6 }}>🔒</div>
                      <p style={{ margin: "0 0 14px", fontSize: 14.5, lineHeight: 1.6, color: T.inkSoft }}>
                        The advanced tier for <strong style={{ color: T.ink }}>{t.name}</strong> unlocks once you've answered at least {ADV_MIN_QUESTIONS} questions here with 80%+ accuracy. {ap.needQuestions > 0 ? `Answer ${ap.needQuestions} more question${ap.needQuestions === 1 ? "" : "s"} to qualify` : `You're at ${Math.round(ap.acc * 100)}% accuracy — get it to 80%+ to unlock`}.
                      </p>
                      <div style={{ maxWidth: 280, margin: "0 auto 14px" }}>
                        <ProgressBar value={Math.min(100, (ap.distinct / ADV_MIN_QUESTIONS) * 100)} />
                        <div style={{ fontSize: 12, color: T.inkFaint, marginTop: 6 }}>{ap.distinct} of {ADV_MIN_QUESTIONS} questions attempted · {Math.round(ap.acc * 100)}% accuracy</div>
                      </div>
                      <button onClick={() => setTab("practice")} style={{ background: T.brand, color: "#0E0F0D", border: "none", borderRadius: T.radiusSm, padding: "11px 22px", fontSize: 14, fontWeight: 600, cursor: "pointer", fontFamily: T.font }}>Practice this topic →</button>
                    </div>
                  )}
                </div>
              );
            })()}

            {/* Live tutor — end of topic */}
            <div style={{ marginTop: 30 }}>
              <SectionHead kicker="Live tutor" title="Still have a question?" sub="Ask anything about this topic and get a direct answer. Always sanity-check numbers against the lesson — even a good tutor can slip." />
              <TopicTutor topic={t} />
            </div>
          </>
        ) : (
          <>
            {/* Question bank */}
            <div style={{ marginTop: 26 }}>
              <SectionHead kicker="Question bank" title={`${t.bank.length} questions, every tier`} sub="Each option is explained — right and wrong — so you learn from the traps, not just the answer." />
              <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
                {t.bank.map((q, i) => (
                  <QuestionCard key={`${t.id}-${i}`} q={{ ...q, topicName: t.name }} qKey={`${t.id}-${i}`} onAnswer={(c) => record({ ...q, key: `${t.id}-${i}`, topicId: t.id }, c)} />
                ))}
              </div>
            </div>

            {/* Practice problems */}
            {t.practice.length > 0 && (
              <div style={{ marginTop: 30 }}>
                <SectionHead kicker="Practice problems" title="Work these yourself" sub="Solve each on paper first. Reveal the solution only after you've committed — that's where real fluency is built." />
                <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
                  {t.practice.map((p, i) => <PracticeProblem key={i} problem={p} index={i} />)}
                </div>
              </div>
            )}

            {/* Build-the-entry exercises */}
            {t.entries && t.entries.w1 && t.entries.w1.length > 0 && (
              <div style={{ marginTop: 30 }}>
                <SectionHead kicker="Build the entry" title="Write the journal entry yourself" sub="Type the debit and credit amounts for each account, then check. This is the skill the exam actually tests — producing entries, not just recognizing them." />
                <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
                  {t.entries.w1.map((e, i) => <EntryBuilder key={i} entry={e} index={i} />)}
                </div>
              </div>
            )}
          </>
        )}

        {/* Path navigation footer */}
        <div style={{ marginTop: 36, paddingTop: 24, borderTop: `1px solid ${T.line}`, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12 }}>
          <button onClick={goPrevInPath} style={{ display: "flex", alignItems: "center", gap: 8, background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radiusSm, padding: "11px 18px", fontSize: 14, fontWeight: 600, color: T.inkSoft, cursor: "pointer", boxShadow: T.shadowSm, fontFamily: T.font, transition: "all 180ms ease" }}
            onMouseEnter={(e) => (e.currentTarget.style.borderColor = T.brand)} onMouseLeave={(e) => (e.currentTarget.style.borderColor = T.line)}>
            ← Previous
          </button>
          <span style={{ fontSize: 12.5, color: T.inkFaint, fontWeight: 500 }}>{pathIndex + 1} / {PATH.length}</span>
          <button onClick={goNextInPath} style={{ display: "flex", alignItems: "center", gap: 8, background: T.brand, border: "none", borderRadius: T.radiusSm, padding: "11px 22px", fontSize: 14, fontWeight: 600, color: "#0E0F0D", cursor: "pointer", boxShadow: T.shadowSm, fontFamily: T.font, transition: "transform 160ms ease" }}
            onMouseEnter={(e) => (e.currentTarget.style.transform = "translateY(-1px)")} onMouseLeave={(e) => (e.currentTarget.style.transform = "translateY(0)")}>
            Next topic →
          </button>
        </div>
      </div>
    );
  };

  // ---------- PRACTICE (adaptive) ----------
  const renderPractice = () => {
    const q = practiceQ;
    return (
      <div style={{ maxWidth: 760, margin: "0 auto", padding: "28px 24px 80px" }}>
        <SectionHead kicker="Adaptive practice" title="Drill your weak spots" sub="This serves questions you missed first, then targets your lowest-accuracy topics. Answer a missed question right twice to clear its flag." />
        <div style={{ display: "flex", gap: 12, marginBottom: 20, flexWrap: "wrap" }}>
          <div style={{ flex: 1, minWidth: 130, background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, padding: 16, boxShadow: T.shadowSm }}>
            <div style={{ fontSize: 24, fontWeight: 700, color: T.ink }}>{practiceN}</div>
            <div style={{ fontSize: 12.5, color: T.inkFaint }}>answered this session</div>
          </div>
          <div style={{ flex: 1, minWidth: 130, background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, padding: 16, boxShadow: T.shadowSm }}>
            <div style={{ fontSize: 24, fontWeight: 700, color: missedCount ? T.gold : T.brand }}>{missedCount}</div>
            <div style={{ fontSize: 12.5, color: T.inkFaint }}>flagged to revisit</div>
          </div>
        </div>
        {bookmarkOnly && (
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, marginBottom: 16, padding: "10px 14px", background: T.brandSoft, border: `1px solid ${T.brand}44`, borderRadius: T.radiusSm }}>
            <span style={{ fontSize: 13, color: T.brandDeep, fontWeight: 600 }}>🔖 Practicing bookmarked questions only</span>
            <button onClick={() => { setBookmarkOnly(false); setPracticeQ(pickAdaptive()); }} style={{ background: "transparent", border: `1px solid ${T.brand}55`, borderRadius: 999, padding: "4px 12px", fontSize: 12, color: T.brandDeep, cursor: "pointer", fontFamily: T.font }}>Exit</button>
          </div>
        )}
        {q ? (
          <>
            <QuestionCard key={`${q.key}-${practiceN}`} q={q} qKey={q.key} showTopic onAnswer={(c) => record(q, c)} />
            <div style={{ display: "flex", gap: 10, marginTop: 18 }}>
              <button onClick={() => dispatch({ type: "bookmark", key: q.key, topicId: q.topicId })}
                title="Bookmark this question to revisit later"
                style={{ flexShrink: 0, background: progress[q.key]?.bookmarked ? T.brandSoft : T.surface, color: progress[q.key]?.bookmarked ? T.brandDeep : T.inkSoft, border: `1px solid ${progress[q.key]?.bookmarked ? T.brand + "66" : T.line}`, borderRadius: T.radiusSm, padding: "14px 18px", fontSize: 15, cursor: "pointer", fontFamily: T.font }}>
                {progress[q.key]?.bookmarked ? "🔖 Saved" : "🔖 Save"}
              </button>
              <button onClick={() => { setPracticeN((n) => n + 1); setPracticeQ(pickAdaptive()); }}
                style={{ flex: 1, background: T.brand, color: "#0E0F0D", border: "none", borderRadius: T.radiusSm, padding: "14px", fontSize: 15, fontWeight: 600, cursor: "pointer", boxShadow: T.shadowSm, fontFamily: T.font }}>
                Next question →
              </button>
            </div>
          </>
        ) : <div style={{ padding: 40, textAlign: "center", color: T.inkFaint }}>Loading…</div>}
      </div>
    );
  };

  // ---------- PROGRESS ----------
  const renderCalc = () => (
    <div style={{ maxWidth: 760, margin: "0 auto", padding: "28px 24px 80px" }}>
      <SectionHead kicker="Tools" title="Live calculators" sub="Plug in any numbers and watch the schedules recompute. Use these to build intuition — change one input and see how the answer moves." />
      <div style={{ display: "flex", flexDirection: "column", gap: 18 }}>
        <BondCalculator />
        <LeaseCalculator />
        <TaxCalculator />
      </div>
    </div>
  );

  const renderExam = () => {
    const mm = String(Math.floor(examTimeLeft / 60)).padStart(2, "0");
    const ss = String(examTimeLeft % 60).padStart(2, "0");
    const lowTime = examTimeLeft <= 60;

    if (examState === "idle") {
      return (
        <div style={{ maxWidth: 680, margin: "0 auto", padding: "28px 24px 80px" }}>
          <SectionHead kicker="Mock exam" title="Simulate test conditions" sub="A timed, mixed-topic exam drawn from all nine areas. No explanations until you finish — just like the real thing." />
          <div style={{ background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, padding: 24, boxShadow: T.shadowSm }}>
            <p style={{ margin: "0 0 18px", fontSize: 14.5, lineHeight: 1.6, color: T.inkSoft }}>Pick a format. Questions are pulled at random across every topic and shuffled, so each attempt is different. A clock runs down; when it hits zero the exam auto-submits.</p>
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {[["Quick check", 10, 15], ["Standard", 20, 30], ["Full mock", 30, 50]].map(([label, count, mins]) => (
                <button key={label} onClick={() => startExam(count, mins)} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "16px 20px", borderRadius: T.radius, border: `1.5px solid ${T.line}`, background: T.surfaceAlt, cursor: "pointer", transition: "all 180ms ease", fontFamily: T.font }}
                  onMouseEnter={(e) => { e.currentTarget.style.borderColor = T.brand; }} onMouseLeave={(e) => { e.currentTarget.style.borderColor = T.line; }}>
                  <span style={{ fontSize: 15.5, fontWeight: 600, color: T.ink }}>{label}</span>
                  <span style={{ fontSize: 13.5, color: T.inkSoft }}>{count} questions · {mins} min</span>
                </button>
              ))}
            </div>
          </div>
        </div>
      );
    }

    if (examState === "running") {
      const q = examQs[examIdx];
      const picked = examAnswers[examIdx];
      const answeredCount = Object.keys(examAnswers).length;
      return (
        <div style={{ maxWidth: 720, margin: "0 auto", padding: "20px 24px 80px" }}>
          {/* Sticky exam bar */}
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, marginBottom: 18, padding: "12px 16px", background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, boxShadow: T.shadowSm }}>
            <span style={{ fontSize: 13.5, color: T.inkSoft, fontWeight: 500 }}>Question {examIdx + 1} of {examQs.length} · {answeredCount} answered</span>
            <span style={{ fontSize: 16, fontWeight: 700, fontFamily: "ui-monospace, Menlo, monospace", color: lowTime ? T.rose : T.ink, padding: "4px 12px", borderRadius: 999, background: lowTime ? T.roseSoft : T.surfaceAlt }}>{mm}:{ss}</span>
          </div>

          <div style={{ background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, padding: 22, boxShadow: T.shadowSm }}>
            <span style={{ fontSize: 12, color: T.inkFaint, fontWeight: 600 }}>{q.topicName}</span>
            <p style={{ margin: "8px 0 0", fontSize: 16, lineHeight: 1.55, fontWeight: 500, color: T.ink }}>{q.q}</p>
            <div style={{ marginTop: 16, display: "flex", flexDirection: "column", gap: 9 }}>
              {q.choices.map((choice, ci) => {
                const sel = picked === ci;
                return (
                  <button key={ci} onClick={() => setExamAnswers((a) => ({ ...a, [examIdx]: ci }))}
                    style={{ display: "flex", alignItems: "flex-start", gap: 12, textAlign: "left", padding: "12px 15px", borderRadius: T.radiusSm, border: `1.5px solid ${sel ? T.brand : T.line}`, background: sel ? T.brandTint : T.surface, color: T.ink, fontSize: 14.5, lineHeight: 1.5, cursor: "pointer", transition: "all 150ms ease", fontFamily: T.font }}>
                    <span style={{ flexShrink: 0, width: 22, height: 22, borderRadius: 6, background: sel ? T.brand : T.surfaceAlt, color: sel ? "#0E0F0D" : T.inkSoft, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12, fontWeight: 700 }}>{String.fromCharCode(65 + ci)}</span>
                    <span style={{ paddingTop: 1 }}>{choice}</span>
                  </button>
                );
              })}
            </div>
          </div>

          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, marginTop: 18 }}>
            <button onClick={() => setExamIdx((i) => Math.max(0, i - 1))} disabled={examIdx === 0}
              style={{ padding: "11px 18px", borderRadius: T.radiusSm, border: `1px solid ${T.line}`, background: T.surface, color: examIdx === 0 ? T.inkFaint : T.inkSoft, fontSize: 14, fontWeight: 600, cursor: examIdx === 0 ? "default" : "pointer", fontFamily: T.font, opacity: examIdx === 0 ? 0.5 : 1 }}>← Prev</button>
            {examIdx < examQs.length - 1 ? (
              <button onClick={() => setExamIdx((i) => i + 1)} style={{ padding: "11px 22px", borderRadius: T.radiusSm, border: "none", background: T.brand, color: "#0E0F0D", fontSize: 14, fontWeight: 600, cursor: "pointer", fontFamily: T.font }}>Next →</button>
            ) : (
              <button onClick={() => setExamState("done")} style={{ padding: "11px 22px", borderRadius: T.radiusSm, border: "none", background: T.gold, color: "#0E0F0D", fontSize: 14, fontWeight: 700, cursor: "pointer", fontFamily: T.font }}>Submit exam</button>
            )}
          </div>
          {/* Question grid jump */}
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginTop: 22 }}>
            {examQs.map((_, i) => (
              <button key={i} onClick={() => setExamIdx(i)} style={{ width: 30, height: 30, borderRadius: 7, border: `1px solid ${i === examIdx ? T.brand : T.line}`, background: examAnswers[i] !== undefined ? T.brandSoft : T.surface, color: examAnswers[i] !== undefined ? T.brandDeep : T.inkFaint, fontSize: 12, fontWeight: 600, cursor: "pointer", fontFamily: T.font }}>{i + 1}</button>
            ))}
          </div>
        </div>
      );
    }

    // done — score + review
    const correct = examQs.filter((q, i) => examAnswers[i] === q.answer).length;
    const pct = examQs.length ? Math.round((correct / examQs.length) * 100) : 0;
    return (
      <div style={{ maxWidth: 720, margin: "0 auto", padding: "28px 24px 80px" }}>
        <div style={{ background: `linear-gradient(135deg, #0C3D2C, #1E7A58)`, borderRadius: T.radiusLg, padding: 30, color: "#fff", boxShadow: T.shadowLg, textAlign: "center" }}>
          <div style={{ fontSize: 13, fontWeight: 600, letterSpacing: "0.06em", textTransform: "uppercase", opacity: 0.85 }}>Exam complete</div>
          <div style={{ fontSize: 48, fontWeight: 700, margin: "8px 0", fontFamily: T.serif }}>{pct}%</div>
          <div style={{ fontSize: 15, opacity: 0.92 }}>{correct} of {examQs.length} correct</div>
        </div>
        <div style={{ display: "flex", gap: 12, marginTop: 18 }}>
          <button onClick={() => setExamState("idle")} style={{ flex: 1, padding: "13px", borderRadius: T.radiusSm, border: "none", background: T.brand, color: "#0E0F0D", fontSize: 14.5, fontWeight: 600, cursor: "pointer", fontFamily: T.font }}>New exam</button>
        </div>
        <h3 style={{ fontSize: 16, fontWeight: 600, color: T.ink, marginTop: 28, marginBottom: 4 }}>Review</h3>
        <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
          {examQs.map((q, i) => {
            const picked = examAnswers[i];
            const right = picked === q.answer;
            return (
              <div key={i} style={{ background: T.surface, border: `1px solid ${right ? T.brand + "44" : T.rose + "44"}`, borderRadius: T.radius, padding: 18, boxShadow: T.shadowSm }}>
                <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 8 }}>
                  <span style={{ fontSize: 12, fontWeight: 700, color: right ? T.brand : T.rose }}>{right ? "✓ Correct" : "✗ Incorrect"}</span>
                  <span style={{ fontSize: 12, color: T.inkFaint }}>· {q.topicName}</span>
                </div>
                <p style={{ margin: "0 0 10px", fontSize: 14.5, fontWeight: 500, color: T.ink, lineHeight: 1.5 }}>{i + 1}. {q.q}</p>
                <div style={{ fontSize: 13.5, lineHeight: 1.55, color: T.brandDeep, background: T.brandSoft, padding: "9px 12px", borderRadius: 8 }}>
                  <strong>{String.fromCharCode(65 + q.answer)}.</strong> {q.why[q.answer]}
                </div>
                {!right && picked !== undefined && (
                  <div style={{ fontSize: 13, lineHeight: 1.55, color: T.rose, background: T.roseSoft, padding: "9px 12px", borderRadius: 8, marginTop: 7 }}>
                    Your answer — <strong>{String.fromCharCode(65 + picked)}.</strong> {q.why[picked]}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    );
  };

  const renderProgress = () => (
    <div style={{ maxWidth: 760, margin: "0 auto", padding: "28px 24px 80px" }}>
      <SectionHead kicker="Progress" title="Where you stand" />
      <div style={{ display: "flex", gap: 14, marginBottom: 24, flexWrap: "wrap", alignItems: "center" }}>
        <div style={{ background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, padding: "20px 22px", boxShadow: T.shadowSm, display: "flex", alignItems: "center", gap: 18 }}>
          <Ring pct={overallPct} size={64} />
          <div>
            <div style={{ fontSize: 13, color: T.inkFaint }}>Overall accuracy</div>
            <div style={{ fontSize: 15, fontWeight: 600, color: T.ink, marginTop: 2 }}>{overallCorrect} of {overallSeen} correct</div>
          </div>
        </div>
        <div style={{ flex: 1, minWidth: 120, background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, padding: 20, boxShadow: T.shadowSm }}>
          <div style={{ fontSize: 26, fontWeight: 700, color: T.ink }}>{topicsStarted}<span style={{ fontSize: 16, color: T.inkFaint }}>/9</span></div>
          <div style={{ fontSize: 12.5, color: T.inkFaint, marginTop: 2 }}>topics started</div>
        </div>
        <div style={{ flex: 1, minWidth: 120, background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, padding: 20, boxShadow: T.shadowSm }}>
          <div style={{ fontSize: 26, fontWeight: 700, color: missedCount ? T.gold : T.brand }}>{missedCount}</div>
          <div style={{ fontSize: 12.5, color: T.inkFaint, marginTop: 2 }}>flagged to revisit</div>
        </div>
      </div>

      {/* Review today — spaced repetition recommendation */}
      {(() => {
        const queue = reviewQueue();
        const marks = bookmarked();
        if (overallSeen === 0) return null;
        return (
          <div style={{ marginBottom: 24 }}>
            <div style={{ background: queue.length ? "linear-gradient(135deg, rgba(224,169,60,0.10), rgba(63,185,133,0.08))" : T.surface, border: `1px solid ${queue.length ? T.gold + "44" : T.line}`, borderRadius: T.radius, padding: 22, boxShadow: T.shadowSm }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
                <span style={{ fontSize: 17 }}>{queue.length ? "🔁" : "✓"}</span>
                <h3 style={{ margin: 0, fontSize: 16, fontWeight: 600, color: T.ink }}>Review today</h3>
              </div>
              {queue.length === 0 ? (
                <p style={{ margin: 0, fontSize: 14, color: T.inkSoft, lineHeight: 1.6 }}>Nothing's due right now — your recent topics are still fresh. Come back tomorrow, or start a new topic from the path.</p>
              ) : (
                <>
                  <p style={{ margin: "0 0 14px", fontSize: 14, color: T.inkSoft, lineHeight: 1.6 }}>These are fading or shaky — revisiting them now, before they slip, is the highest-value thing you can do. Ordered by urgency.</p>
                  <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                    {queue.slice(0, 5).map((r) => (
                      <button key={r.id} onClick={() => goTopic(r.id)} style={{ display: "flex", alignItems: "center", gap: 12, textAlign: "left", background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radiusSm, padding: "11px 14px", cursor: "pointer", fontFamily: T.font, transition: "border-color 160ms ease" }}
                        onMouseEnter={(e) => (e.currentTarget.style.borderColor = T.brand)} onMouseLeave={(e) => (e.currentTarget.style.borderColor = T.line)}>
                        <span style={{ fontSize: 17 }}>{byId[r.id].icon}</span>
                        <div style={{ flex: 1, minWidth: 0 }}>
                          <div style={{ fontSize: 14, fontWeight: 600, color: T.ink }}>{r.name}</div>
                          <div style={{ fontSize: 12, color: T.inkFaint, marginTop: 2 }}>{Math.round(r.acc * 100)}% accuracy · last studied {r.daysSince >= 999 ? "a while ago" : r.daysSince < 1 ? "today" : Math.round(r.daysSince) + "d ago"}{r.missedHere ? ` · ${r.missedHere} flagged` : ""}</div>
                        </div>
                        <span style={{ fontSize: 12.5, color: T.gold, fontWeight: 600 }}>Review →</span>
                      </button>
                    ))}
                  </div>
                </>
              )}
              {marks.length > 0 && (
                <div style={{ marginTop: 16, paddingTop: 14, borderTop: `1px solid ${T.lineSoft}` }}>
                  <div style={{ fontSize: 12.5, fontWeight: 600, color: T.inkSoft, marginBottom: 8 }}>🔖 Bookmarked questions ({marks.length})</div>
                  <button onClick={() => { setView("practice"); setPracticeQ(marks[0]); setBookmarkOnly(true); }} style={{ background: T.surfaceAlt, border: `1px solid ${T.line}`, borderRadius: T.radiusSm, padding: "8px 14px", fontSize: 13, color: T.ink, cursor: "pointer", fontFamily: T.font }}>Practice bookmarked only →</button>
                </div>
              )}
            </div>
          </div>
        );
      })()}

      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {PATH.map((p, i) => {
          const t = byId[p.id];
          const acc = topicAcc(p.id);
          const seen = topicSeen(p.id);
          return (
            <button key={p.id} onClick={() => goTopic(p.id)} style={{ display: "flex", alignItems: "center", gap: 16, textAlign: "left", background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, padding: "16px 18px", cursor: "pointer", boxShadow: T.shadowSm, transition: "all 180ms ease", fontFamily: T.font }}
              onMouseEnter={(e) => (e.currentTarget.style.borderColor = T.brand)} onMouseLeave={(e) => (e.currentTarget.style.borderColor = T.line)}>
              <span style={{ fontSize: 12, fontWeight: 700, color: T.inkFaint, width: 20 }}>{String(i + 1).padStart(2, "0")}</span>
              <span style={{ fontSize: 20 }}>{t.icon}</span>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 14.5, fontWeight: 600, color: T.ink }}>{t.name}</div>
                <div style={{ marginTop: 7 }}><ProgressBar value={(acc || 0) * 100} fill={acc !== null && acc < 0.7 ? T.gold : T.brand} /></div>
              </div>
              <span style={{ fontSize: 12.5, color: T.inkFaint, fontWeight: 500, minWidth: 96, textAlign: "right" }}>{seen === 0 ? "Not started" : `${Math.round((acc || 0) * 100)}% · ${seen} done`}</span>
            </button>
          );
        })}
      </div>

      {/* Mock exam history — trend over attempts */}
      {(() => {
        const hist = examHistory();
        if (!hist.length) return null;
        const max = 100;
        return (
          <div style={{ marginTop: 24, background: T.surface, border: `1px solid ${T.line}`, borderRadius: T.radius, padding: 22, boxShadow: T.shadowSm }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
              <span style={{ fontSize: 16 }}>📈</span>
              <h3 style={{ margin: 0, fontSize: 16, fontWeight: 600, color: T.ink }}>Mock exam history</h3>
            </div>
            <p style={{ margin: "0 0 16px", fontSize: 13, color: T.inkFaint }}>Your last {hist.length} {hist.length === 1 ? "attempt" : "attempts"}. Watch the trend, not any single score.</p>
            {/* Bar trend */}
            <div style={{ display: "flex", alignItems: "flex-end", gap: 8, height: 120, padding: "0 4px", marginBottom: 14 }}>
              {hist.slice(-12).map((h, i) => {
                const col = h.pct >= 80 ? T.brand : h.pct >= 60 ? T.gold : T.rose;
                return (
                  <div key={i} style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 5 }}>
                    <span style={{ fontSize: 11, fontWeight: 700, color: col }}>{h.pct}</span>
                    <div title={`${h.correct}/${h.total} on ${new Date(h.at).toLocaleDateString()}`} style={{ width: "100%", maxWidth: 34, height: `${(h.pct / max) * 90}px`, minHeight: 4, background: col, borderRadius: "5px 5px 2px 2px", opacity: 0.5 + 0.5 * ((i + 1) / Math.min(hist.length, 12)) }} />
                  </div>
                );
              })}
            </div>
            {/* Weakest topics across all attempts */}
            {(() => {
              const agg = {};
              hist.forEach((h) => Object.entries(h.byTopic || {}).forEach(([id, t]) => {
                const a = agg[id] || { name: t.name, correct: 0, total: 0 };
                a.correct += t.correct; a.total += t.total; agg[id] = a;
              }));
              const ranked = Object.values(agg).filter((a) => a.total >= 2).map((a) => ({ ...a, acc: a.correct / a.total })).sort((a, b) => a.acc - b.acc).slice(0, 3);
              if (!ranked.length) return null;
              return (
                <div style={{ paddingTop: 14, borderTop: `1px solid ${T.lineSoft}` }}>
                  <div style={{ fontSize: 12.5, fontWeight: 600, color: T.inkSoft, marginBottom: 10 }}>Weakest under exam conditions</div>
                  <div style={{ display: "flex", flexDirection: "column", gap: 7 }}>
                    {ranked.map((a, i) => (
                      <div key={i} style={{ display: "flex", alignItems: "center", gap: 10 }}>
                        <span style={{ fontSize: 13, color: T.ink, minWidth: 96 }}>{a.name}</span>
                        <div style={{ flex: 1 }}><ProgressBar value={a.acc * 100} fill={a.acc < 0.6 ? T.rose : a.acc < 0.8 ? T.gold : T.brand} /></div>
                        <span style={{ fontSize: 12, color: T.inkFaint, minWidth: 64, textAlign: "right" }}>{Math.round(a.acc * 100)}% · {a.total}q</span>
                      </div>
                    ))}
                  </div>
                </div>
              );
            })()}
          </div>
        );
      })()}

      {overallSeen > 0 && (
        <button onClick={() => { if (window.confirm("Reset all progress?")) dispatch({ type: "reset" }); }}
          style={{ marginTop: 22, background: "none", border: `1px solid ${T.line}`, borderRadius: T.radiusSm, padding: "9px 16px", fontSize: 13, color: T.inkFaint, cursor: "pointer", fontFamily: T.font }}>Reset progress</button>
      )}
    </div>
  );

  return (
    <div ref={scrollRef} style={{ fontFamily: T.font, background: T.bg, color: T.ink, minHeight: "100%", height: "100vh", overflowY: "auto", WebkitFontSmoothing: "antialiased" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Newsreader:opsz,wght@6..72,400;6..72,500;6..72,600&display=swap');
        @keyframes fadeIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }
        * { box-sizing: border-box; }
        button { font-family: inherit; }
        ::selection { background: rgba(63,185,133,0.3); color: ${T.ink}; }
        ::-webkit-scrollbar { width: 12px; height: 12px; }
        ::-webkit-scrollbar-track { background: ${T.bg}; }
        ::-webkit-scrollbar-thumb { background: ${T.line}; border-radius: 999px; border: 3px solid ${T.bg}; }
        ::-webkit-scrollbar-thumb:hover { background: #3a3d35; }
        @keyframes tutorBlink { 0%, 100% { opacity: 0.35; } 50% { opacity: 1; } }
        .tutorDots::after { content: "…"; animation: tutorBlink 1.2s ease-in-out infinite; }
      `}</style>
      <Header />
      {view === "home" && renderHome()}
      {view === "path" && renderPath()}
      {view === "topic" && renderTopic()}
      {view === "practice" && renderPractice()}
      {view === "calc" && renderCalc()}
      {view === "exam" && renderExam()}
      {view === "progress" && renderProgress()}
    </div>
  );
}
